@dataclass(frozen=True)
class StyleRule:
    """Parsed CSS rule representation."""
    selector: str
    properties: Dict[str, str]
    line_number: int


class CSSModuleParser:
    """Robust parser for CSS module files with nested selector support."""

    def __init__(self, file_path: Path):
        self.file_path = file_path
        self.content = self._load_content()
        self.rules = self._parse_rules()

    def _load_content(self) -> str:
        """Load and validate CSS file content."""
        if not self.file_path.exists():
            raise FileNotFoundError(f"CSS file not found: {self.file_path}")
        content = self.file_path.read_text(encoding="utf-8")
        if not content.strip():
            raise ValueError("CSS file is empty")
        return content

    def _parse_rules(self) -> List[StyleRule]:
        """Parse CSS rules handling nested selectors and comments."""
        rules = []
        # Remove comments
        content = re.sub(r"/\*.*?\*/", "", self.content, flags=re.DOTALL)

        # Match top-level rules (handles nested via brace counting)
        pattern = re.compile(
            r"([^{}]+)\{([^{}]*)\}",
            re.DOTALL
        )

        for match in pattern.finditer(content):
            selector = match.group(1).strip()
            body = match.group(2).strip()

            # Skip @media and @keyframes blocks (handled separately)
            if selector.startswith("@"):
                continue

            # Parse properties
            properties = {}
            for prop_match in re.finditer(
                r"([a-zA-Z-]+)\s*:\s*([^;]+);",
                body
            ):
                prop_name = prop_match.group(1).strip()
                prop_value = prop_match.group(2).strip()
                properties[prop_name] = prop_value

            if properties:
                line_number = self.content[:self.content.find(selector)].count("\n") + 1
                rules.append(StyleRule(selector, properties, line_number))

        return rules

    def get_rule(self, selector: str) -> StyleRule:
        """Retrieve a specific rule by selector."""
        for rule in self.rules:
            if rule.selector == selector:
                return rule
        raise KeyError(f"Selector not found: {selector}")

    def get_all_selectors(self) -> Set[str]:
        """Return all defined selectors."""
        return {rule.selector for rule in self.rules}

    def get_property_value(self, selector: str, property_name: str) -> str:
        """Get specific property value from a selector."""
        rule = self.get_rule(selector)
        if property_name not in rule.properties:
            raise KeyError(
                f"Property '{property_name}' not found in selector '{selector}'"
            )
        return rule.properties[property_name]


