class TestCSSVariables:
    """Validate consistent CSS variable usage."""

    @pytest.fixture(autouse=True)
    def setup(self, css_parser):
        self.parser = css_parser

    def test_all_colors_use_variables(self):
        """All color properties must reference CSS variables."""
        color_props = {"color", "background-color", "border-color", "border-bottom", "border-top"}
        for rule in self.parser.rules:
            for prop in color_props:
                if prop in rule.properties:
                    value = rule.properties[prop]
                    if "color" in prop or prop in {"border-bottom", "border-top"}:
                        assert "var(--" in value, \
                            f"Property '{prop}' in '{rule.selector}' must use CSS variable, got: {value}"

    def test_no_hardcoded_colors(self):
        """No hex/rgb/rgba/hsl colors should be hardcoded."""
        hex_pattern = re.compile(r"#[0-9a-fA-F]{3,8}\b")
        rgb_pattern = re.compile(r"rgba?\(|hsla?\(")

        for rule in self.parser.rules:
            for prop, value in rule.properties.items():
                assert not hex_pattern.search(value), \
                    f"Hardcoded hex color in '{rule.selector}' property '{prop}': {value}"
                assert not rgb_pattern.search(value), \
                    f"Hardcoded rgb/hsl color in '{rule.selector}' property '{prop}': {value}"

    def test_known_variables_used(self):
        """Only known CSS variables should be referenced."""
        known_vars = {
            "--background-color",
            "--text-color",
            "--text-secondary-color",
            "--primary-color",
            "--secondary-color",
            "--card-background",
            "--border-color",
        }

        var_pattern = re.compile(r"var\((--[\w-]+)\)")
        for rule in self.parser.rules:
            for prop, value in rule.properties.items():
                for match in var_pattern.finditer(value):
                    var_name = match.group(1)
                    assert var_name in known_vars, \
                        f"Unknown CSS variable '{var_name}' in '{rule.selector}' property '{prop}'"


