class TestResponsiveDesign:
    """Validate responsive design constraints."""

    def test_no_fixed_widths(self, css_parser):
        """No fixed pixel widths should be used for main containers."""
        fixed_width_props = {"width", "min-width", "max-width"}
        for rule in css_parser.rules:
            for prop in fixed_width_props:
                if prop in rule.properties:
                    value = rule.properties[prop]
                    # Allow max-width for content constraint
                    if prop == "max-width":
                        continue
                    assert not value.endswith("px"), \
                        f"Fixed width '{value}' in '{rule.selector}' property '{prop}'"

    def test_responsive_units_used(self):
        """Layout dimensions should use relative units."""
        dimension_props = {"padding", "margin", "font-size"}
        for rule in css_parser.rules:
            for prop in dimension_props:
                if prop in rule.properties:
                    value = rule.properties[prop]
                    # Allow px for specific spacing values
                    if prop in {"padding", "margin"}:
                        continue
                    assert any(unit in value for unit in ["em", "rem", "%", "vh", "vw"]), \
                        f"Property '{prop}' in '{rule.selector}' should use relative units, got: {value}"


