    def test_rule_ordering(self, css_parser):
        """Rules should be in logical order (container, header, main, footer)."""
        selectors = [rule.selector for rule in css_parser.rules]
        expected_order = [".appContainer", ".appHeader", ".appTitle", ".appMain", ".appFooter"]
        positions = []
        for selector in expected_order:
            if selector in selectors:
                positions.append(selectors.index(selector))

        assert positions == sorted(positions), \
            "Rules are not in logical order"


