class TestCrossBrowserCompatibility:
    """Validate cross-browser compatible CSS patterns."""

    def test_box_sizing_prefixed(self, css_parser):
        """box-sizing should have vendor prefixes."""
        for rule in css_parser.rules:
            if "box-sizing" in rule.properties:
                # Modern browsers support unprefixed, but should be present
                assert rule.properties["box-sizing"] in {"border-box", "content-box"}, \
                    f"Invalid box-sizing value in '{rule.selector}'"

    def test_flexbox_modern_syntax(self, css_parser):
        """Flexbox should use modern syntax."""
        for rule in css_parser.rules:
            if "display" in rule.properties and "flex" in rule.properties["display"]:
                # Modern flex properties
                assert "flex-direction" in rule.properties or \
                       "flex-grow" in rule.properties or \
                       "justify-content" in rule.properties or \
                       "align-items" in rule.properties, \
                    f"Rule '{rule.selector}' uses flex but lacks flex properties"

    def test_transition_compatibility(self, css_parser):
        """Transitions should have vendor prefixes."""
        for rule in css_parser.rules:
            if "transition" in rule.properties:
                transition = rule.properties["transition"]
                assert "all" not in transition, \
                    f"Transition in '{rule.selector}' should not use 'all'"


